export type PartConfig = {
  category: string;
  id?: string;
  className?: string;
};

const PARTS_CONFIG: PartConfig[] = [
  { category: 'body', className: 'AvatarBody' },
  { category: 'hair', className: 'Hair' },
  { category: 'hat', className: 'Hat' },
  { category: 'tshirt', className: 'Tshirt' }
];

export default PARTS_CONFIG;

import Clothe from './structure/parts/clothes/Clothe';

export type ClotheConstructor = new (id?: string) => Clothe;

class ClotheRegistry {
  private map: Map<string, ClotheConstructor> = new Map();

  register(key: string, ctor: ClotheConstructor) {
    this.map.set(key, ctor);
  }

  create(key: string, id?: string): Clothe | null {
    const ctor = this.map.get(key);
    if (!ctor) return null;
    return new ctor(id);
  }

  has(key: string): boolean {
    return this.map.has(key);
  }
}

const instance = new ClotheRegistry();
export default instance;

export enum ZPriority {
  WALL = 0,
  FLOOR = 1,
  FURNITURE = 2,
  AVATAR = 3,
  EFFECT = 4
}

/**
 * Compute a z-index for an entity.
 * Combines vertical position (y) and a priority layer to give stable ordering.
 */
export function compute(entity: { y?: number; layer?: number; offset?: number }): number {
  const y = Math.round((entity.y ?? 0) * 100);
  const layer = (entity.layer ?? ZPriority.FURNITURE) & 0xff;
  const offset = Math.floor((entity.offset ?? 0) & 0xff);

  // produce ordering: layer has highest significance, then y, then offset
  // multiply layer to keep large gaps between priorities
  return layer * 1000000 + y * 10 + offset;
}

export function validateClotheJson(json: any): string[] {
  const errors: string[] = [];
  if (!json) {
    errors.push('empty json');
    return errors;
  }
  if (!json.frames || typeof json.frames !== 'object') errors.push('missing or invalid "frames"');
  if (!json.meta || !json.meta.image) errors.push('missing meta.image');
  return errors;
}

export function validateFurnitureJson(json: any): string[] {
  const errors: string[] = [];
  if (!json) {
    errors.push('empty json');
    return errors;
  }
  if (!json.frames || typeof json.frames !== 'object') errors.push('missing or invalid "frames"');
  // optional: validate points in frames
  return errors;
}

